package page

import (
	"path"
	"path/filepath"
	"strings"
	"sync"

	"github.com/gohugoio/hugo/common/paths"
	"github.com/gohugoio/hugo/common/urls"
	"github.com/gohugoio/hugo/helpers"
	"github.com/gohugoio/hugo/output"
	"github.com/gohugoio/hugo/resources/kinds"
)

const slash = "/"

// TargetPathDescriptor describes how a file path for a given resource
// should look like on the file system. The same descriptor is then later used to
// create both the permalinks and the relative links, paginator URLs etc.
//
// The big motivating behind this is to have only one source of truth for URLs,
// and by that also get rid of most of the fragile string parsing/encoding etc.

type TargetPathDescriptor struct {
	PathSpec *helpers.PathSpec

	Type output.Format
	Kind string

	Path    *paths.Path
	Section *paths.Path

	// For regular content pages this is either
	// 1) the Slug, if set,
	// 2) the file base name (TranslationBaseName).
	BaseName string

	// Typically a language prefix added to file paths.
	PrefixFilePath string

	// Typically a language prefix added to links.
	PrefixLink string

	// If in multihost mode etc., every link/path needs to be prefixed, even
	// if set in URL.
	ForcePrefix bool

	// URL from front matter if set. Will override any Slug etc.
	URL string

	// Used to create paginator links.
	Addends string

	// The expanded permalink if defined for the section, ready to use.
	ExpandedPermalink string

	// Some types cannot have uglyURLs, even if globally enabled, RSS being one example.
	UglyURLs bool
}

// TODO(bep) move this type.
type TargetPaths struct {
	// Where to store the file on disk relative to the publish dir. OS slashes.
	TargetFilename string

	// The directory to write sub-resources of the above.
	SubResourceBaseTarget string

	// The base for creating links to sub-resources of the above.
	SubResourceBaseLink string

	// The relative permalink to this resources. Unix slashes.
	Link string
}

func (p TargetPaths) RelPermalink(s *helpers.PathSpec) string {
	return s.PrependBasePath(p.Link, false)
}

func (p TargetPaths) PermalinkForOutputFormat(s *helpers.PathSpec, f output.Format) string {
	var baseURL urls.BaseURL
	var err error
	if f.Protocol != "" {
		baseURL, err = s.Cfg.BaseURL().WithProtocol(f.Protocol)
		if err != nil {
			return ""
		}
	} else {
		baseURL = s.Cfg.BaseURL()
	}
	baseURLstr := baseURL.String()
	return s.PermalinkForBaseURL(p.Link, baseURLstr)
}

func (o OutputFormat) CreateTargetPaths(d TargetPathDescriptor) TargetPaths {
	pb := getPagePathBuilder(d)
	defer putPagePathBuilder(pb)

	format := o.Format

	var fullSuffix string
	if format.MediaType.SuffixesCSV != "" {
		fullSuffix = format.MediaType.Delimiter + strings.Split(format.MediaType.SuffixesCSV, ",")[0]
	}

	pb.assemble(fullSuffix, format.Root, format.Ugly, format.NoUgly, format.BaseName, d.Path.IsBundle())

	if pb.shouldSanitize() {
		pb.sanitizeElements(!d.PathSpec.Cfg.DisablePathToLower())
	}

	link := pb.Link()
	if d.URL != "" {
		link = paths.URLEscape(link)
	} else {
		// This is slightly faster for when we know we don't have any
		// query or scheme etc.
		link = paths.PathEscape(link)
	}
	if link == "" {
		link = "/"
	}

	return pb.result(link)
}

func (p *pagePathBuilder) assemble(fullSuffix string, isRoot, formatUgly, formatNoUgly bool, formatBaseName string, isBundle bool) {
	// Normalize all file Windows paths to simplify what's next.
	if helpers.FilePathSeparator != "/" {
		p.d.PrefixFilePath = filepath.ToSlash(p.d.PrefixFilePath)
	}

	if !isRoot && p.d.URL != "" && !strings.HasPrefix(p.d.URL, "/") {
		// Treat this as a context relative URL
		p.d.ForcePrefix = true
	}

	if p.d.URL != "" {
		p.d.URL = filepath.ToSlash(p.d.URL)
		if strings.Contains(p.d.URL, "..") {
			p.d.URL = path.Join("/", p.d.URL)
		}
	}

	if isRoot && !p.d.ForcePrefix {
		p.d.PrefixFilePath = ""
		p.d.PrefixLink = ""
	}

	p.fullSuffix = fullSuffix

	// The top level index files, i.e. the home page etc., needs
	// the index base even when uglyURLs is enabled.
	needsBase := true

	p.isUgly = (p.d.UglyURLs || formatUgly) && !formatNoUgly
	p.baseNameSameAsType = !isBundle && p.d.BaseName != "" && p.d.BaseName == formatBaseName

	if p.d.ExpandedPermalink == "" && p.baseNameSameAsType {
		p.isUgly = true
	}

	if p.d.Type == output.HTTPStatusHTMLFormat || p.d.Type == output.SitemapFormat || p.d.Type == output.RobotsTxtFormat {
		p.noSubResources = true
	} else if p.d.Kind != kinds.KindPage && p.d.URL == "" && p.d.Section.Base() != "/" {
		if p.d.ExpandedPermalink != "" {
			p.Add(p.d.ExpandedPermalink)
		} else {
			p.Add(p.d.Section.Base())
		}
		needsBase = false
	}

	if p.d.Type.Path != "" {
		p.Add(p.d.Type.Path)
	}

	if p.d.Kind != kinds.KindHome && p.d.URL != "" {
		p.Add(paths.FieldsSlash(p.d.URL)...)

		if p.d.Addends != "" {
			p.Add(p.d.Addends)
		}

		hasDot := strings.Contains(p.d.URL, ".")
		hasSlash := strings.HasSuffix(p.d.URL, "/")

		if hasSlash || !hasDot {
			p.Add(p.d.Type.BaseName + p.fullSuffix)
		} else if hasDot {
			p.fullSuffix = paths.Ext(p.d.URL)
		}

		if p.IsHtmlIndex() {
			p.linkUpperOffset = 1
		}

		if p.d.ForcePrefix {

			// Prepend language prefix if not already set in URL
			if p.d.PrefixFilePath != "" && !strings.HasPrefix(p.d.URL, "/"+p.d.PrefixFilePath) {
				p.prefixPath = p.d.PrefixFilePath
			}

			if p.d.PrefixLink != "" && !strings.HasPrefix(p.d.URL, "/"+p.d.PrefixLink) {
				p.prefixLink = p.d.PrefixLink
			}
		}
	} else if !kinds.IsBranch(p.d.Kind) {
		if p.d.ExpandedPermalink != "" {
			p.Add(p.d.ExpandedPermalink)
		} else {
			if dir := p.d.Path.ContainerDir(); dir != "" {
				p.Add(dir)
			}
			if p.d.BaseName != "" {
				p.Add(p.d.BaseName)
			} else {
				p.Add(p.d.Path.BaseNameNoIdentifier())
			}
		}

		if p.d.Addends != "" {
			p.Add(p.d.Addends)
		}

		if p.isUgly {
			p.ConcatLast(p.fullSuffix)
		} else {
			p.Add(p.d.Type.BaseName + p.fullSuffix)
		}

		if p.IsHtmlIndex() {
			p.linkUpperOffset = 1
		}

		if p.d.PrefixFilePath != "" {
			p.prefixPath = p.d.PrefixFilePath
		}

		if p.d.PrefixLink != "" {
			p.prefixLink = p.d.PrefixLink
		}
	} else {
		if p.d.Addends != "" {
			p.Add(p.d.Addends)
		}

		needsBase = needsBase && p.d.Addends == ""

		if needsBase || !p.isUgly {
			p.Add(p.d.Type.BaseName + p.fullSuffix)
		} else {
			p.ConcatLast(p.fullSuffix)
		}

		if p.IsHtmlIndex() {
			p.linkUpperOffset = 1
		}

		if p.d.PrefixFilePath != "" {
			p.prefixPath = p.d.PrefixFilePath
		}

		if p.d.PrefixLink != "" {
			p.prefixLink = p.d.PrefixLink
		}
	}
}

func (p *pagePathBuilder) shouldSanitize() bool {
	// if page URL is explicitly set in frontmatter,
	// preserve its value without sanitization
	return p.d.Kind != kinds.KindPage || p.d.URL == ""
}

func (p *pagePathBuilder) sanitizeElements(toLower bool) {
	for i, el := range p.els {
		s := p.d.PathSpec.MakePath(el)
		if toLower {
			s = strings.ToLower(s)
		}
		p.els[i] = s
	}
}

func (p *pagePathBuilder) result(link string) TargetPaths {
	var tp TargetPaths
	tp.TargetFilename = filepath.FromSlash(p.PathFile())
	if !p.noSubResources {
		tp.SubResourceBaseTarget = p.PathDir()
		tp.SubResourceBaseLink = p.LinkDir()
	}
	tp.Link = link
	return tp
}

// When adding state here, remember to update putPagePathBuilder.
type pagePathBuilder struct {
	els []string

	d TargetPathDescriptor

	// Builder state.
	isUgly             bool
	baseNameSameAsType bool
	noSubResources     bool
	fullSuffix         string // File suffix including any ".".
	prefixLink         string
	prefixPath         string
	linkUpperOffset    int
}

func (p *pagePathBuilder) Add(el ...string) {
	// Filter empty and slashes.
	n := 0
	for _, e := range el {
		if e != "" && e != slash {
			el[n] = e
			n++
		}
	}
	el = el[:n]

	p.els = append(p.els, el...)
}

func (p *pagePathBuilder) ConcatLast(s string) {
	if len(p.els) == 0 {
		p.Add(s)
		return
	}
	old := p.els[len(p.els)-1]
	if old == "" {
		p.els[len(p.els)-1] = s
		return
	}
	if old[len(old)-1] == '/' {
		old = old[:len(old)-1]
	}
	p.els[len(p.els)-1] = old + s
}

func (p *pagePathBuilder) IsHtmlIndex() bool {
	return p.Last() == "index.html"
}

func (p *pagePathBuilder) Last() string {
	if p.els == nil {
		return ""
	}
	return p.els[len(p.els)-1]
}

func (p *pagePathBuilder) Link() string {
	link := p.Path(p.linkUpperOffset)

	if p.baseNameSameAsType {
		link = strings.TrimSuffix(link, p.d.BaseName)
	}

	if p.prefixLink != "" {
		link = "/" + p.prefixLink + link
	}

	if p.linkUpperOffset > 0 && !strings.HasSuffix(link, "/") {
		link += "/"
	}

	return link
}

func (p *pagePathBuilder) LinkDir() string {
	if p.noSubResources {
		return ""
	}

	pathDir := p.PathDirBase()

	if p.prefixLink != "" {
		pathDir = "/" + p.prefixLink + pathDir
	}

	return pathDir
}

func (p *pagePathBuilder) Path(upperOffset int) string {
	upper := len(p.els)
	if upperOffset > 0 {
		upper -= upperOffset
	}
	pth := path.Join(p.els[:upper]...)
	return paths.AddLeadingSlash(pth)
}

func (p *pagePathBuilder) PathDir() string {
	dir := p.PathDirBase()
	if p.prefixPath != "" {
		dir = "/" + p.prefixPath + dir
	}
	return dir
}

func (p *pagePathBuilder) PathDirBase() string {
	if p.noSubResources {
		return ""
	}

	dir := p.Path(0)
	isIndex := strings.HasPrefix(p.Last(), p.d.Type.BaseName+".")

	if isIndex {
		dir = paths.Dir(dir)
	} else {
		dir = strings.TrimSuffix(dir, p.fullSuffix)
	}

	if dir == "/" {
		dir = ""
	}

	return dir
}

func (p *pagePathBuilder) PathFile() string {
	dir := p.Path(0)
	if p.prefixPath != "" {
		dir = "/" + p.prefixPath + dir
	}
	return dir
}

func (p *pagePathBuilder) Prepend(el ...string) {
	p.els = append(p.els[:0], append(el, p.els[0:]...)...)
}

var pagePathBuilderPool = &sync.Pool{
	New: func() any {
		return &pagePathBuilder{}
	},
}

func getPagePathBuilder(d TargetPathDescriptor) *pagePathBuilder {
	b := pagePathBuilderPool.Get().(*pagePathBuilder)
	b.d = d
	return b
}

func putPagePathBuilder(b *pagePathBuilder) {
	b.els = b.els[:0]
	b.fullSuffix = ""
	b.baseNameSameAsType = false
	b.isUgly = false
	b.noSubResources = false
	b.prefixLink = ""
	b.prefixPath = ""
	b.linkUpperOffset = 0
	pagePathBuilderPool.Put(b)
}

